import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { collection, query, where, onSnapshot } from 'firebase/firestore';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate } from 'react-router-dom';
import Layout from '../components/Layout';

export default function Inbox() {
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  const [chats, setChats] = useState([]);

  useEffect(() => {
    if (!currentUser) return;
    
    const q = query(collection(db, 'chats'), where('users', 'array-contains', currentUser.uid));

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const chatList = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      // Urutkan chat terbaru di atas
      chatList.sort((a, b) => (b.lastMessageTime?.toMillis() || 0) - (a.lastMessageTime?.toMillis() || 0));
      setChats(chatList);
    });

    return () => unsubscribe();
  }, [currentUser]);

  return (
    <Layout>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '25px' }}>
        <h2 style={{ margin: 0 }}>Pesan Masuk</h2>
        <span style={{ background: 'var(--forest-green)', color: 'white', padding: '5px 12px', borderRadius: '20px', fontSize: '0.85rem', fontWeight: '600' }}>
          {chats.length} Obrolan
        </span>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        {chats.length === 0 ? (
          <div style={{ padding: '40px', textAlign: 'center', background: 'var(--glass-card)', borderRadius: '20px', border: '1px solid var(--glass-border)' }}>
            <h3 style={{ margin: '0 0 10px 0', color: 'var(--text-dark)' }}>Kotak Masuk Kosong 📭</h3>
            <p style={{ margin: 0, color: 'var(--text-muted)' }}>Belum ada obrolan. Mulai pinjam buku di halaman Jelajah!</p>
          </div>
        ) : (
          chats.map(chat => {
            const isOwner = chat.ownerId === currentUser.uid;
            const chatPartner = isOwner ? chat.borrowerName : "Pemilik Buku";
            // Cek apakah ada notif unread untuk akun kita
            const isUnread = chat.unreadBy && chat.unreadBy.includes(currentUser.uid);

            return (
              <div 
                key={chat.id} 
                onClick={() => navigate(`/dashboard/chat/${chat.id}`)}
                style={{
                  padding: '20px', background: isUnread ? 'rgba(76, 175, 80, 0.1)' : 'var(--glass-card)',
                  borderRadius: '15px', border: '1px solid var(--glass-border)', cursor: 'pointer', display: 'flex',
                  justifyContent: 'space-between', alignItems: 'center', transition: 'transform 0.2s'
                }}
              >
                <div style={{ position: 'relative' }}>
                  {/* Titik merah notifikasi */}
                  {isUnread && <span style={{ position: 'absolute', left: '-15px', top: '5px', width: '10px', height: '10px', background: '#FF5252', borderRadius: '50%' }}></span>}
                  
                  <h3 style={{ margin: '0 0 5px 0', fontSize: '1.1rem', color: 'var(--text-dark)', fontWeight: isUnread ? 'bold' : 'normal' }}>
                    Buku: {chat.bookTitle}
                  </h3>
                  <p style={{ margin: 0, color: isUnread ? 'var(--text-dark)' : 'var(--text-muted)', fontSize: '0.9rem', fontWeight: isUnread ? 'bold' : 'normal' }}>
                    {chat.lastMessage || "Belum ada pesan..."}
                  </p>
                </div>
                <div style={{ background: 'var(--forest-green)', color: 'white', padding: '8px 15px', borderRadius: '10px', fontSize: '0.9rem' }}>
                  Buka Chat
                </div>
              </div>
            );
          })
        )}
      </div>
    </Layout>
  );
}