import React, { useState, useEffect } from 'react';
import { NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { auth, db } from '../firebase';
import { signOut } from "firebase/auth";
import { collection, query, where, onSnapshot } from 'firebase/firestore';

export default function Layout({ children }) {
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0); 

  useEffect(() => {
    const savedMode = localStorage.getItem('darkMode') === 'true';
    setIsDarkMode(savedMode);
    if (savedMode) document.body.classList.add('dark-mode');
  }, []);

  useEffect(() => {
    if (!currentUser) return;
    const q = query(
      collection(db, 'chats'), 
      where('unreadBy', 'array-contains', currentUser.uid)
    );
    const unsubscribe = onSnapshot(q, (snapshot) => {
      setUnreadCount(snapshot.size); 
    });
    return () => unsubscribe();
  }, [currentUser]);

  const toggleDarkMode = () => {
    setIsDarkMode(!isDarkMode);
    if (!isDarkMode) {
      document.body.classList.add('dark-mode');
      localStorage.setItem('darkMode', 'true'); 
    } else {
      document.body.classList.remove('dark-mode');
      localStorage.setItem('darkMode', 'false'); 
    }
  };

  const handleLogout = () => {
    signOut(auth);
    navigate('/');
  };

  return (
    <div className="dashboard-container">
      <nav className="sidebar">
        <h2>Pustaka Party</h2>
        
        <NavLink to="/dashboard" end className={({isActive}) => isActive ? "sidebar-link active" : "sidebar-link"}>
          <span>❖</span> Dashboard
        </NavLink>
        
        <NavLink to="/dashboard/my-books" className={({isActive}) => isActive ? "sidebar-link active" : "sidebar-link"}>
          <span>📚</span> Buku Saya
        </NavLink>

        {/* --- INI MENU BARU: PINJAMANKU --- */}
        <NavLink to="/dashboard/borrowed" className={({isActive}) => isActive ? "sidebar-link active" : "sidebar-link"}>
          <span>📖</span> Pinjamanku
        </NavLink>
        {/* --------------------------------- */}

        <NavLink to="/dashboard/explore" className={({isActive}) => isActive ? "sidebar-link active" : "sidebar-link"}>
          <span>🔍</span> Jelajah
        </NavLink>
        
        <NavLink to="/dashboard/inbox" className={({isActive}) => isActive ? "sidebar-link active" : "sidebar-link"} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div><span>💬</span> Pesan</div>
          {unreadCount > 0 && (
            <span style={{ background: '#FF5252', color: 'white', fontSize: '0.75rem', padding: '2px 8px', borderRadius: '10px', fontWeight: 'bold' }}>
              {unreadCount}
            </span>
          )}
        </NavLink>

        <NavLink to="/dashboard/profile" className={({isActive}) => isActive ? "sidebar-link active" : "sidebar-link"}>
          <span>👤</span> Profil
        </NavLink>
        
        <button onClick={handleLogout} className="logout-btn">
          <span>🚪</span> Keluar
        </button>
      </nav>

      <main className="main-content">
        <header className="header">
          <div>
            <h1>Halo, {currentUser?.displayName?.split(' ')[0] || 'Teman'}!</h1>
            <p>Siap untuk berbagi buku hari ini?</p>
          </div>
          
          <div style={{ display: 'flex', gap: '20px', alignItems: 'center' }}>
            <button 
              onClick={toggleDarkMode} 
              style={{ background: 'none', border: 'none', fontSize: '1.5rem', cursor: 'pointer', transition: 'transform 0.3s', transform: isDarkMode ? 'rotate(360deg)' : 'rotate(0deg)' }}
              title={isDarkMode ? "Beralih ke Light Mode" : "Beralih ke Dark Mode"}
            >
              {isDarkMode ? '☀️' : '🌙'}
            </button>

            <div style={{ position: 'relative' }}>
              <img src={currentUser?.photoURL || 'https://via.placeholder.com/50'} alt="Profile" style={{ width: '50px', height: '50px', borderRadius: '15px', objectFit: 'cover' }} />
              <span style={{ position: 'absolute', top: '-5px', right: '-5px', width: '15px', height: '15px', background: '#4CAF50', borderRadius: '50%', border: '2px solid white' }}></span>
            </div>
          </div>
        </header>
        {children}
      </main>
    </div>
  );
}

